package org.example.backend.service;
import org.example.backend.entity.*;
import org.example.backend.mapper.*;
import org.example.backend.service.impl.*;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import java.time.LocalDateTime;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class ResourceCrudBehaviorTest {
    final BusinessLoopService loop=mock(BusinessLoopService.class);
    @Test void environmentTemplatesNormalizeStatusesAndRecordCreateUpdateDelete(){EnvironmentTemplateMapper mapper=mock(EnvironmentTemplateMapper.class);EnvironmentTemplateService service=new EnvironmentTemplateServiceImpl(mapper,loop);when(mapper.insertTemplate(any())).thenAnswer(call->{((EnvironmentTemplateEntity)call.getArgument(0)).setId(1L);return 1;});EnvironmentTemplateEntity saved=new EnvironmentTemplateEntity();saved.setId(1L);saved.setName("课程模板");saved.setCourse("程序设计");saved.setStatus("可复用");when(mapper.getTemplate(1L)).thenReturn(saved);when(mapper.listTemplates()).thenReturn(List.of(saved));assertSame(saved,service.createTemplate(null));var input=ArgumentCaptor.forClass(EnvironmentTemplateEntity.class);verify(mapper).insertTemplate(input.capture());assertEquals("新环境模板",input.getValue().getName());assertEquals("通用课程",input.getValue().getCourse());assertEquals("试运行",input.getValue().getStatus());assertEquals("primary",input.getValue().getTagType());service.updateTemplate(1L,saved);assertEquals("success",saved.getTagType());saved.setStatus("待更新");saved.setTagType(null);service.updateTemplate(1L,saved);assertEquals("warning",saved.getTagType());assertEquals(List.of(saved),service.deleteTemplate(1L));assertEquals(List.of(saved),service.listTemplates());assertNull(service.updateTemplate(99L,new EnvironmentTemplateEntity()));service.listTeachers();verify(mapper).listTeachers();}
    @Test void environmentBatchReplaceAndResetPreserveFullDefaultTemplates(){EnvironmentTemplateMapper mapper=mock(EnvironmentTemplateMapper.class);EnvironmentTemplateService service=new EnvironmentTemplateServiceImpl(mapper,loop);service.replaceTemplates(null);verify(mapper,never()).insertTemplate(any());service.replaceTemplates(Collections.singletonList(null));verify(mapper).insertTemplate(argThat(template->"新环境模板".equals(template.getName())));clearInvocations(mapper);service.resetTemplates();var input=ArgumentCaptor.forClass(EnvironmentTemplateEntity.class);verify(mapper,times(3)).insertTemplate(input.capture());assertEquals(List.of("Java Web 标准环境","网络攻防隔离环境","AI GPU 训练环境"),input.getAllValues().stream().map(EnvironmentTemplateEntity::getName).toList());assertTrue(input.getAllValues().stream().allMatch(template->template.getOs()!=null&&template.getSoftwareList()!=null&&template.getLabs()!=null));}
    @Test void softwareAliasesSynchronizeAndInstallationTimeIsSetForInstalledState(){softwareMapper mapper=mock(softwareMapper.class);softwareService service=new softwareServiceImpl(mapper,loop);softwareEntity input=new softwareEntity();input.setName("IDEA");input.setVersion("2026");input.setLicense("教学授权");input.setType("开发工具");assertSame(input,service.InserterLabSoftware(input).getData());assertEquals("IDEA",input.getSoftwareName());assertEquals("2026",input.getSoftwareVersion());assertEquals("教学授权",input.getLicenseInfo());assertEquals("开发工具",input.getRemark());assertEquals("待安装",input.getStatus());input.setStatus("已安装");service.updateLabSoftware(1L,input);assertEquals(1L,input.getId());assertNotNull(input.getInstallTime());service.deleteLabSoftware(1L);verify(mapper).deleteLabSoftware(1L);service.getLabSoftware();verify(mapper).getLabSoftware();}
    @Test void legacySoftwareFieldsRemainReadableAndExplicitInstallTimeIsRetained(){softwareMapper mapper=mock(softwareMapper.class);softwareService service=new softwareServiceImpl(mapper,loop);softwareEntity input=new softwareEntity();input.setSoftwareName("MySQL");input.setSoftwareVersion("8");input.setLicenseInfo("GPL");LocalDateTime installed=LocalDateTime.of(2026,10,18,10,0);input.setInstallTime(installed);service.InserterLabSoftware(input);assertEquals("MySQL",input.getName());assertEquals("8",input.getVersion());assertEquals("GPL",input.getLicense());assertEquals("已安装",input.getStatus());assertEquals(installed,input.getInstallTime());}
    @Test void labListsHonorManagerScopeAndNormalizeMissingResults(){LabMapper mapper=mock(LabMapper.class);LabService service=new LabServiceImpl(mapper,loop);when(mapper.getLabs()).thenReturn(null);when(mapper.getLabsByManagerUserId(7)).thenReturn(null);assertEquals(List.of(),service.getLabs());assertEquals(List.of(),service.getLabs(null));assertEquals(List.of(),service.getLabs(7));assertNull(service.getLabById(99));LabEntity lab=new LabEntity();lab.setId(1);when(mapper.getLabById(1)).thenReturn(lab);assertSame(lab,service.getLabById(1));}
    @Test void labCreateAndUpdateAuditCanonicalRecordsOrFallbackWhenReadBackIsMissing(){LabMapper mapper=mock(LabMapper.class);LabService service=new LabServiceImpl(mapper,loop);LabEntity input=new LabEntity();input.setId(1);input.setLabName("机房");assertSame(input,service.addLab(input));assertEquals("开放",input.getOpenStatus());verify(loop).recordEvent("lab","create","机房","开放",Map.of("labId",1,"capacity",0));when(mapper.getLabById(1)).thenReturn(input);service.updateLab(1,input);service.updateLab(99,input);verify(loop).recordEvent("lab","update","99","已更新",Map.of("labId",99));service.updateLabs(null);service.updateLabs(List.of());service.updateLabs(List.of(input,new LabEntity()));verify(mapper,times(2)).updateLab(1,input);}
    @Test void labDeletionRemovesDependentRowsBeforeParentAndRejectsMissingOrConcurrentDeletion(){LabMapper mapper=mock(LabMapper.class);LabService service=new LabServiceImpl(mapper,loop);LabEntity lab=new LabEntity();lab.setId(1);lab.setLabName("机房");when(mapper.getLabById(1)).thenReturn(lab);when(mapper.deleteLab(1)).thenReturn(1);service.deleteLab(1);var order=inOrder(mapper);order.verify(mapper).getLabById(1);order.verify(mapper).deleteRepairsByLabId(1);order.verify(mapper).deleteReservationsByLabId(1);order.verify(mapper).deleteCourseEnvironmentsByLabId(1);order.verify(mapper).deleteLabSoftwareByLabId(1);order.verify(mapper).deleteDevicesByLabId(1);order.verify(mapper).deleteLab(1);assertThrows(IllegalArgumentException.class,()->service.deleteLab(99));when(mapper.deleteLab(1)).thenReturn(0);assertThrows(IllegalArgumentException.class,()->service.deleteLab(1));}
}
